mapper.select:
SELECT fn.* FROM metadata_function_node fn
JOIN metadata_module m ON fn.module_code = m.module_code AND m.status = 1
WHERE fn.module_code = #{moduleCode} AND fn.node_code = #{nodeCode}

    AND fn.business_code = #{businessCode}

SELECT fn.* FROM metadata_function_node fn
JOIN metadata_module m ON fn.module_code = m.module_code AND m.status = 1
WHERE fn.module_code = #{moduleCode}

    AND fn.business_code = #{businessCode}

ORDER BY fn.sort ASC, fn.create_time ASC

SELECT fn.* FROM metadata_function_node fn
JOIN metadata_module m ON fn.module_code = m.module_code AND m.status = 1
WHERE fn.related_table_code = #{relatedTableCode}

    AND fn.business_code = #{businessCode}

ORDER BY fn.sort ASC, fn.create_time ASC

SELECT COUNT(*) FROM metadata_function_node fn
JOIN metadata_module m ON fn.module_code = m.module_code AND m.status = 1
WHERE fn.module_code = #{moduleCode}

    AND fn.business_code = #{businessCode}

SELECT fn.* FROM metadata_function_node fn
JOIN metadata_module m ON fn.module_code = m.module_code AND m.status = 1
WHERE fn.module_code = #{moduleCode}

    AND fn.business_code = #{businessCode}

ORDER BY fn.sort ASC, fn.create_time ASC
LIMIT #{pageRequest.offset}, #{pageRequest.size}
